return new {agents=new[]{"Assets/Prefabs/Chapter01/Scout.prefab","Assets/Prefabs/UnitPrefab.prefab"}.Select(p=>new{p,json=UnityEditor.EditorJsonUtility.ToJson(UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>(p).GetComponent<UnityEngine.AI.NavMeshAgent>())}).ToArray(),types=Enumerable.Range(0,UnityEngine.AI.NavMesh.GetSettingsCount()).Select(i=>UnityEngine.AI.NavMesh.GetSettingsByIndex(i)).Select(s=>new{s.agentTypeID,s.agentRadius,s.agentClimb,s.agentHeight}).ToArray(),ui=UnityEngine.Object.FindObjectOfType<UİManager>().GetType().GetFields().Where(f=>f.FieldType==typeof(GameObject)&&f.Name.Contains("Prefab")).Select(f=>new{f.Name,path=UnityEditor.AssetDatabase.GetAssetPath(f.GetValue(UnityEngine.Object.FindObjectOfType<UİManager>()) as UnityEngine.Object)}).ToArray()};
